import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.CQdiwDJy.js";const u=JSON.parse('{"title":"内置工具","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tools.md","filePath":"guide/tools.md","lastUpdated":1788601681000}'),r={name:"guide/tools.md"};function l(i,t,s,c,n,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="内置工具" tabindex="-1">内置工具 <a class="header-anchor" href="#内置工具" aria-label="Permalink to &quot;内置工具&quot;">​</a></h1><p>Tau 的工具层是<strong>确定性</strong>的：每个工具都是纯注册表驱动的函数，AI 计划只能调用注册表里存在的工具，不存在&quot;AI 现场发明工具&quot;。内置工具分四族，全部低风险只读优先、可变操作默认干跑。</p><h2 id="file-族-——-文件系统" tabindex="-1">file 族 —— 文件系统 <a class="header-anchor" href="#file-族-——-文件系统" aria-label="Permalink to &quot;file 族 —— 文件系统&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>说明</th><th>风险</th></tr></thead><tbody><tr><td><code>file.find</code></td><td>按 glob 递归查找（自动剪枝 node_modules/.git/dist）</td><td>low</td></tr><tr><td><code>file.read</code></td><td>带行号读取文本文件（offset/limit、拒绝二进制与 &gt;2MB；v0.5.0 起结构化结果携带检测到的语言）</td><td>low</td></tr><tr><td><code>file.list</code></td><td>单目录非递归列表</td><td>low</td></tr><tr><td><code>file.stat</code></td><td>大小 / 类型 / mtime</td><td>low</td></tr><tr><td><code>file.tree</code></td><td>深度受限的目录树</td><td>low</td></tr><tr><td><code>file.rename</code></td><td>正则批量重命名（默认干跑）</td><td>medium</td></tr><tr><td><code>file.write</code></td><td>受控写入（覆盖/追加，默认干跑，硬限制在工作区内）</td><td>medium</td></tr></tbody></table><p><strong>刻意没有 delete。</strong> 第一方工具族里不存在删除原语——删除只能走经审查的 shell 步骤或你自己的手。这是写在安全模型里的设计决策，不是遗漏。</p><h2 id="sys-net-text-族" tabindex="-1">sys / net / text 族 <a class="header-anchor" href="#sys-net-text-族" aria-label="Permalink to &quot;sys / net / text 族&quot;">​</a></h2><ul><li><strong>sys</strong>：进程、磁盘、环境等系统只读探查。</li><li><strong>net</strong>：HTTP GET 等网络只读操作。</li><li><strong>text</strong>：在文件内容上做查找、统计等文本操作。</li></ul><p>每个工具在 CLI 都有对应命令（如 <code>tau file read</code>），也可以在 WebUI 的 Tools 面板浏览全部参数 schema。</p><h2 id="风险与确认" tabindex="-1">风险与确认 <a class="header-anchor" href="#风险与确认" aria-label="Permalink to &quot;风险与确认&quot;">​</a></h2><p>工具声明的 <code>risk</code> 决定执行门的宽严：low 只读工具在计划里可直接运行；medium 工具（写操作）默认干跑预览，设置 <code>execute: true</code> 才真正生效；安全审查层还会对计划里的每个写路径做独立复核（纵深防御——审查只会加强工具自身的检查，不会放松）。</p><h2 id="file-read-的语言元数据-v0-5-0" tabindex="-1">file.read 的语言元数据（v0.5.0） <a class="header-anchor" href="#file-read-的语言元数据-v0-5-0" aria-label="Permalink to &quot;file.read 的语言元数据（v0.5.0）&quot;">​</a></h2><p><code>file.read</code> 的结构化结果现在携带 <code>path</code> 与 <code>language</code>——从文件名做最佳努力的语言推断（shiki 兼容 id，未知回落 <code>text</code>）。WebUI 的文件查看器用它选择高亮语法，工具层与前端共享同一份检测逻辑，由一致性测试防漂移。</p>',12)])])}const m=e(r,[["render",l]]);export{u as __pageData,m as default};
